response:
我会写成可重复执行的安装脚本：依赖检查、venv、后端安装、模型下载、前端构建、数据库初始化、自检、快捷方式都分步计时；模型下载 URL 采用环境变量覆盖，避免把不确定地址硬编码死。

PowerShell
# scripts/install.ps1
#requires -version 5.1
<#
PHS one-click installer.

Run:
  powershell -ExecutionPolicy Bypass -File scripts/install.ps1

Optional:
  -SkipModelDownload
  -SkipFrontend
  -SkipShortcut

Model URL overrides:
  $env:PHS_SAM2_URL
  $env:PHS_CUTIE_URL
  $env:PHS_COSYVOICE2_URL
  $env:PHS_WATERMARK_V6_URL
  $env:PHS_COVER_URL
#>

param(
    [string]$ProjectRoot = "",
    [switch]$SkipModelDownload,
    [switch]$SkipFrontend,
    [switch]$SkipShortcut,
    [switch]$ContinueOnMissingTools,
    [switch]$UseChinaMirror
)

$ErrorActionPreference = "Stop"
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8

if (-not $ProjectRoot) {
    $ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
    $ProjectRoot = Resolve-Path (Join-Path $ScriptDir "..")
} else {
    $ProjectRoot = Resolve-Path $ProjectRoot
}

$Script:ProjectRoot = [string]$ProjectRoot
$Script:RuntimeDir = Join-Path $Script:ProjectRoot "runtime"
$Script:ModelsDir = Join-Path $Script:RuntimeDir "models"
$Script:Results = @()
$Script:PythonExe = $null
$Script:PythonArgs = @()

New-Item -ItemType Directory -Force -Path $Script:RuntimeDir, $Script:ModelsDir | Out-Null

function Write-Info($msg) { Write-Host "[INFO] $msg" -ForegroundColor Cyan }
function Write-Ok($msg) { Write-Host "[PASS] $msg" -ForegroundColor Green }
function Write-Warn2($msg) { Write-Host "[WARN] $msg" -ForegroundColor Yellow }
function Write-Fail($msg) { Write-Host "[FAIL] $msg" -ForegroundColor Red }

function Add-Result($Name, $Status, $Seconds, $Detail, $Suggestion = "") {
    $Script:Results += [pscustomobject]@{
        Step       = $Name
        Status     = $Status
        Seconds    = [math]::Round($Seconds, 2)
        Detail     = $Detail
        Suggestion = $Suggestion
    }
}

function Invoke-Step {
    param(
        [string]$Name,
        [scriptblock]$Action,
        [string]$Suggestion = "",
        [bool]$Fatal = $true
    )
    Write-Host ""
    Write-Info "开始: $Name"
    $sw = [Diagnostics.Stopwatch]::StartNew()
    try {
        & $Action
        $sw.Stop()
        Write-Ok "$Name 完成，用时 $([math]::Round($sw.Elapsed.TotalSeconds, 2))s"
        Add-Result $Name "PASS" $sw.Elapsed.TotalSeconds "OK" ""
    } catch {
        $sw.Stop()
        $detail = $_.Exception.Message
        Write-Fail "$Name 失败: $detail"
        if ($Suggestion) { Write-Warn2 "修复建议: $Suggestion" }
        Add-Result $Name "FAIL" $sw.Elapsed.TotalSeconds $detail $Suggestion
        if ($Fatal) { throw }
    }
}

function Invoke-WarnStep {
    param(
        [string]$Name,
        [scriptblock]$Action,
        [string]$Suggestion = ""
    )
    Write-Host ""
    Write-Info "检查: $Name"
    $sw = [Diagnostics.Stopwatch]::StartNew()
    try {
        & $Action
        $sw.Stop()
        Write-Ok "$Name 通过，用时 $([math]::Round($sw.Elapsed.TotalSeconds, 2))s"
        Add-Result $Name "PASS" $sw.Elapsed.TotalSeconds "OK" ""
    } catch {
        $sw.Stop()
        $detail = $_.Exception.Message
        Write-Warn2 "$Name 警告: $detail"
        if ($Suggestion) { Write-Warn2 "修复建议: $Suggestion" }
        Add-Result $Name "WARN" $sw.Elapsed.TotalSeconds $detail $Suggestion
        if (-not $ContinueOnMissingTools) {
            Write-Warn2 "继续安装。若希望缺失工具也中断，可移除 ContinueOnMissingTools 逻辑。"
        }
    }
}

function Test-Cmd($Name) {
    return $null -ne (Get-Command $Name -ErrorAction SilentlyContinue)
}

function Invoke-Native {
    param(
        [string]$Exe,
        [string[]]$Args = @(),
        [string]$Cwd = ""
    )
    if ($Cwd) { Push-Location $Cwd }
    try {
        & $Exe @Args
        if ($LASTEXITCODE -ne 0) {
            throw "$Exe $($Args -join ' ') exited with code $LASTEXITCODE"
        }
    } finally {
        if ($Cwd) { Pop-Location }
    }
}

function Get-Python312 {
    $candidates = @()
    if ($env:PYTHON) {
        $candidates += [pscustomobject]@{ Exe = $env:PYTHON; Args = @() }
    }
    $candidates += [pscustomobject]@{ Exe = "python"; Args = @() }
    $candidates += [pscustomobject]@{ Exe = "py"; Args = @("-3.12") }

    foreach ($c in $candidates) {
        try {
            $args = @()
            if ($c.Args) { $args += $c.Args }
            $args += "--version"
            $out = (& $c.Exe @args 2>&1) -join " "
            if ($out -match "Python\s+(\d+)\.(\d+)\.(\d+)") {
                $maj = [int]$Matches[1]
                $min = [int]$Matches[2]
                if ($maj -gt 3 -or ($maj -eq 3 -and $min -ge 12)) {
                    return [pscustomobject]@{ Exe = $c.Exe; Args = $c.Args; Version = $out.Trim() }
                }
            }
        } catch {}
    }
    throw "未找到 Python 3.12+。请安装 Python 3.12+ 并加入 PATH，或设置 `$env:PYTHON。"
}

function Invoke-Python {
    param([string[]]$Args)
    $all = @()
    if ($Script:PythonArgs) { $all += $Script:PythonArgs }
    $all += $Args
    Invoke-Native -Exe $Script:PythonExe -Args $all -Cwd $Script:ProjectRoot
}

function Get-DirSizeBytes([string]$Path) {
    if (-not (Test-Path $Path)) { return 0 }
    $item = Get-Item $Path
    if (-not $item.PSIsContainer) { return $item.Length }
    $sum = 0
    Get-ChildItem $Path -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object { $sum += $_.Length }
    return $sum
}

function Find-ExistingModel {
    param([string[]]$Patterns, [int]$MinMB)
    if (-not (Test-Path $Script:ModelsDir)) { return $null }
    $minBytes = $MinMB * 1MB
    $files = Get-ChildItem $Script:ModelsDir -Recurse -File -ErrorAction SilentlyContinue
    foreach ($p in $Patterns) {
        $hit = $files | Where-Object { $_.Name -like $p -or $_.FullName -like "*$($p.Trim('*'))*" } |
            Sort-Object Length -Descending | Select-Object -First 1
        if ($hit -and $hit.Length -ge $minBytes) { return $hit.FullName }
    }
    return $null
}

function Download-File {
    param([string]$Url, [string]$OutFile)
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $OutFile) | Out-Null
    $tmp = "$OutFile.tmp"
    if (Test-Path $tmp) { Remove-Item $tmp -Force }
    Write-Info "下载: $Url"
    Invoke-WebRequest -Uri $Url -OutFile $tmp -UseBasicParsing
    Move-Item $tmp $OutFile -Force
}

function Ensure-Model {
    param(
        [string]$Name,
        [string]$Target,
        [int]$MinMB,
        [string[]]$Patterns,
        [string]$UrlEnv,
        [string]$DefaultUrl = ""
    )

    $found = Find-ExistingModel -Patterns $Patterns -MinMB $MinMB
    if ($found) {
        $size = [math]::Round((Get-Item $found).Length / 1MB, 1)
        Write-Ok "$Name 已存在: $found ($size MB)"
        return
    }

    if (Test-Path $Target) {
        $sizeBytes = Get-DirSizeBytes $Target
        if ($sizeBytes -ge ($MinMB * 1MB)) {
            Write-Ok "$Name 已存在: $Target ($([math]::Round($sizeBytes / 1MB, 1)) MB)"
            return
        }
    }

    if ($SkipModelDownload) {
        Write-Warn2 "$Name 缺失，但已跳过模型下载。"
        return
    }

    $url = [Environment]::GetEnvironmentVariable($UrlEnv)
    if (-not $url) { $url = $DefaultUrl }
    if (-not $url) {
        Write-Warn2 "$Name 缺失，且未配置下载地址。设置环境变量 $UrlEnv 后重新运行。"
        return
    }

    $isZip = $url.ToLower().EndsWith(".zip")
    if ($isZip) {
        $zip = Join-Path $env:TEMP "$Name.zip"
        Download-File -Url $url -OutFile $zip
        New-Item -ItemType Directory -Force -Path $Target | Out-Null
        Expand-Archive -Path $zip -DestinationPath $Target -Force
        Remove-Item $zip -Force -ErrorAction SilentlyContinue
    } else {
        Download-File -Url $url -OutFile $Target
    }

    $sizeAfter = Get-DirSizeBytes $Target
    if ($sizeAfter -lt ($MinMB * 1MB)) {
        throw "$Name 下载后大小异常: $([math]::Round($sizeAfter / 1MB, 1)) MB < $MinMB MB"
    }
    Write-Ok "$Name 下载完成: $Target"
}

function Check-VersionNode {
    if (-not (Test-Cmd "node")) { throw "未找到 node。请安装 Node.js 18+。" }
    $v = (& node --version).Trim()
    if ($v -match "v(\d+)\.") {
        if ([int]$Matches[1] -lt 18) { throw "Node.js 版本过低: $v。请安装 Node.js 18+。" }
    }
    if (-not (Test-Cmd "npm")) { throw "未找到 npm。请重新安装 Node.js 并勾选 npm。" }
    Write-Ok "Node.js $v / npm $((& npm --version).Trim())"
}

function Create-LauncherAndShortcut {
    $startPath = Join-Path $Script:ProjectRoot "scripts\start.ps1"
    if (-not (Test-Path $startPath)) {
        $content = @"
# Auto-generated by scripts/install.ps1
`$ErrorActionPreference = "Stop"
Set-Location "$($Script:ProjectRoot)"
if (Test-Path ".venv\Scripts\Activate.ps1") { . ".venv\Scripts\Activate.ps1" }
Write-Host "[PHS] Runtime self-check..." -ForegroundColor Cyan
python -m phs.runtime.self_check
Write-Host "[PHS] Starting backend..." -ForegroundColor Cyan
`$candidates = @(
    @("-m","phs.cli","serve"),
    @("-m","phs.cli","run"),
    @("-m","uvicorn","phs.api.main:app","--host","127.0.0.1","--port","8080"),
    @("-m","uvicorn","phs.server.main:app","--host","127.0.0.1","--port","8080")
)
foreach (`$args in `$candidates) {
    python @args
    if (`$LASTEXITCODE -eq 0) { exit 0 }
}
Write-Host "[PHS] No known start command succeeded. Please check phs.cli." -ForegroundColor Red
pause
"@
        Set-Content -Path $startPath -Value $content -Encoding UTF8
    }

    $desktop = [Environment]::GetFolderPath("Desktop")
    $shortcutPath = Join-Path $desktop "PHS.lnk"
    $shell = New-Object -ComObject WScript.Shell
    $shortcut = $shell.CreateShortcut($shortcutPath)
    $shortcut.TargetPath = "powershell.exe"
    $shortcut.Arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$startPath`""
    $shortcut.WorkingDirectory = $Script:ProjectRoot
    $shortcut.Description = "Start PHS"
    $shortcut.IconLocation = "powershell.exe,0"
    $shortcut.Save()
    Write-Ok "桌面快捷方式已创建: $shortcutPath"
}

Write-Host ""
Write-Host "========================================" -ForegroundColor DarkYellow
Write-Host " PHS 一键安装程序" -ForegroundColor DarkYellow
Write-Host " ProjectRoot: $Script:ProjectRoot" -ForegroundColor DarkYellow
Write-Host "========================================" -ForegroundColor DarkYellow

Invoke-Step "检查 Python 3.12+" {
    $py = Get-Python312
    $Script:PythonExe = $py.Exe
    $Script:PythonArgs = $py.Args
    Write-Ok "$($py.Version) -> $($py.Exe) $($py.Args -join ' ')"
} "安装 Python 3.12+，并加入 PATH；或设置 `$env:PYTHON 指向 python.exe。"

Invoke-Step "检查 Node.js / npm" {
    Check-VersionNode
} "安装 Node.js 18+ LTS，并确认 node/npm 在 PATH。"

Invoke-WarnStep "检查 FFmpeg / FFprobe" {
    if (-not (Test-Cmd "ffmpeg")) { throw "未找到 ffmpeg" }
    if (-not (Test-Cmd "ffprobe")) { throw "未找到 ffprobe" }
    Write-Ok ((& ffmpeg -version 2>&1 | Select-Object -First 1) -join "")
} "安装 FFmpeg，并把 bin 目录加入 PATH。"

Invoke-WarnStep "检查 libvips" {
    if (-not (Test-Cmd "vips")) { throw "未找到 vips/libvips" }
    Write-Ok ((& vips --version 2>&1 | Select-Object -First 1) -join "")
} "安装 libvips，并把 vips.exe 所在目录加入 PATH。"

Invoke-Step "创建虚拟环境" {
    $venv = Join-Path $Script:ProjectRoot ".venv"
    if (-not (Test-Path $venv)) {
        Invoke-Python @("-m", "venv", ".venv")
    }
    $Script:PythonExe = Join-Path $venv "Scripts\python.exe"
    $Script:PythonArgs = @()
    if (-not (Test-Path $Script:PythonExe)) { throw "虚拟环境 python 不存在: $Script:PythonExe" }
    Write-Ok "venv ready: $venv"
} "删除损坏的 .venv 后重试。"

Invoke-Step "安装后端依赖 pip install -e ." {
    $pipArgs = @("-m", "pip", "install", "--upgrade", "pip", "setuptools", "wheel")
    Invoke-Python $pipArgs
    if ($UseChinaMirror) {
        Invoke-Python @("-m", "pip", "install", "-e", ".", "-i", "https://pypi.tuna.tsinghua.edu.cn/simple")
    } else {
        Invoke-Python @("-m", "pip", "install", "-e", ".")
    }
} "检查 pyproject.toml/setup.py、网络、pip 源和 C++/CUDA 依赖。"

Invoke-Step "下载/校验模型权重" {
    Ensure-Model `
        -Name "WatermarkSeg v6" `
        -Target (Join-Path $Script:ModelsDir "watermarkseg\v6.onnx") `
        -MinMB 1 `
        -Patterns @("*watermark*v6*.onnx", "*watermark*v6*.pt", "*watermarkseg*v6*") `
        -UrlEnv "PHS_WATERMARK_V6_URL"

    Ensure-Model `
        -Name "SAM2" `
        -Target (Join-Path $Script:ModelsDir "sam2\sam2_hiera_large.pt") `
        -MinMB 800 `
        -Patterns @("*sam2*hiera*large*.pt", "sam2_hiera_large.pt") `
        -UrlEnv "PHS_SAM2_URL" `
        -DefaultUrl "https://dl.fbaipublicfiles.com/segment_anything_2/072824/sam2_hiera_large.pt"

    Ensure-Model `
        -Name "Cutie" `
        -Target (Join-Path $Script:ModelsDir "cutie\cutie.pth") `
        -MinMB 100 `
        -Patterns @("*cutie*.pth", "*cutie*.pt") `
        -UrlEnv "PHS_CUTIE_URL"

    Ensure-Model `
        -Name "CosyVoice2" `
        -Target (Join-Path $Script:ModelsDir "CosyVoice2") `
        -MinMB 100 `
        -Patterns @("*cosyvoice2*", "*CosyVoice2*") `
        -UrlEnv "PHS_COSYVOICE2_URL"

    Ensure-Model `
        -Name "COVER" `
        -Target (Join-Path $Script:ModelsDir "cover\cover.pt") `
        -MinMB 1 `
        -Patterns @("*cover*.pt", "*cover*.onnx", "*COVER*") `
        -UrlEnv "PHS_COVER_URL"
} "模型下载失败时，手动下载到 runtime\models，或设置对应 PHS_*_URL 环境变量。"

if (-not $SkipFrontend) {
    Invoke-Step "构建前端 phs/web" {
        $web = Join-Path $Script:ProjectRoot "phs\web"
        if (-not (Test-Path $web)) { throw "前端目录不存在: $web" }
        if (-not (Test-Path (Join-Path $web "package.json"))) { throw "缺少 package.json: $web" }
        Invoke-Native -Exe "npm" -Args @("install") -Cwd $web
        Invoke-Native -Exe "npm" -Args @("run", "build") -Cwd $web
    } "检查 Node.js 版本、package.json、npm 源；必要时删除 node_modules 后重试。"
} else {
    Write-Warn2 "已跳过前端构建。"
}

Invoke-Step "初始化数据库 python -m phs.cli init" {
    Invoke-Python @("-m", "phs.cli", "init")
} "确认 phs.cli 存在 init 命令；检查数据库目录写入权限。"

Invoke-Step "运行 Runtime 自检" {
    Invoke-Python @("-m", "phs.runtime.self_check")
} "根据 runtime/reports/self_check.md 修复 FAIL 项。"

if (-not $SkipShortcut) {
    Invoke-Step "创建桌面快捷方式" {
        Create-LauncherAndShortcut
    } "如果系统禁止 COM 快捷方式创建，请手动运行 scripts/start.ps1。"
} else {
    Write-Warn2 "已跳过桌面快捷方式。"
}

Write-Host ""
Write-Host "========================================" -ForegroundColor DarkYellow
Write-Host " 安装结果汇总" -ForegroundColor DarkYellow
Write-Host "========================================" -ForegroundColor DarkYellow
$Script:Results | Format-Table -AutoSize Step, Status, Seconds, Detail

$failed = $Script:Results | Where-Object { $_.Status -eq "FAIL" }
if ($failed.Count -gt 0) {
    Write-Fail "安装未完全成功。请优先修复 FAIL 项。"
    foreach ($f in $failed) {
        if ($f.Suggestion) { Write-Warn2 "$($f.Step): $($f.Suggestion)" }
    }
    exit 1
}

Write-Ok "PHS 安装完成。建议查看 runtime/reports/self_check.md，并运行桌面快捷方式启动。"
exit 0
